package com.trampolim.api.fairs;
import java.time.*;import java.util.*;import java.util.function.Function;
import static com.trampolim.api.fairs.FairRules.*;
import com.trampolim.api.hub.*;import com.trampolim.api.radar.RadarBridge;import com.trampolim.api.geography.TerritorialCatalog;import com.trampolim.api.company.CompanyRadarController;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@Service @ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class FairService {
 private final JdbcTemplate db;private final HubAccess access;private final TerritorialCatalog geo;private final RadarBridge bridge;private final TransactionTemplate tx;
 public FairService(@Qualifier("empresasJdbcTemplate")JdbcTemplate db,@Qualifier("empresasTransactionManager")PlatformTransactionManager manager,HubAccess access,TerritorialCatalog geo,RadarBridge bridge){this.db=db;this.tx=new TransactionTemplate(manager);this.access=access;this.geo=geo;this.bridge=bridge;}
 private Map<String,Object> event(long org,long id,boolean lock){return db.queryForList("SELECT * FROM job_fairs WHERE organization_id=? AND id=?"+(lock?" FOR UPDATE":""),org,id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Evento não encontrado nesta organização."));}
 private void orgLock(long org){if(db.queryForList("SELECT id FROM enterprise_organizations WHERE id=? FOR UPDATE",org).isEmpty())missing();}
 private void audit(String email,long id,String action){db.update("INSERT INTO job_fair_audit(event_id,actor_user_id,action,revision) SELECT f.id,u.id,?,f.revision FROM job_fairs f JOIN company_users u ON LOWER(u.email)=LOWER(?) WHERE f.id=?",action,email,id);}
 private void bump(long id){db.update("UPDATE job_fairs SET revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",id);}
 private Map<String,Object> write(String email,long org,long id,long revision,String action,Function<Map<String,Object>,Object> work){return tx.execute(status->{orgLock(org);access.require(email,org,true);access.additionalWrite(org);var row=event(org,id,true);if(number(row,"revision")!=revision||Set.of("ARCHIVED","CANCELLED").contains(row.get("status")))conflict();work.apply(row);bump(id);audit(email,id,action);return decorate(event(org,id,false));});}
 private Map<String,Object> decorate(Map<String,Object> row){Instant start=time(row.get("starts_at")),end=time(row.get("ends_at")),now=Instant.now();String status=row.get("status").toString();row.put("municipalityLabel",geo.label(row.get("municipality_code")));row.put("starts_at",start.toString());row.put("ends_at",end.toString());row.put("phase",!status.equals("PUBLISHED")?status:!end.isAfter(now)?"ENDED":start.isAfter(now)?"UPCOMING":"LIVE");row.put("registrationOpen",Boolean.TRUE.equals(row.get("registration_enabled"))&&status.equals("PUBLISHED")&&end.isAfter(now));return row;}
 private Map<String,Object> pageRows(List<Map<String,Object>> rows,int limit){for(var row:rows)if(row.containsKey("municipality_code"))decorate(row);return HubService.pageResult(rows,limit);}
 private Definition validate(Definition p){if(p==null)bad("Informe o evento.");var start=instant(p.startsAt());var end=instant(p.endsAt());period(start,end);String mode=text(p.modality(),16,true);if(!Set.of("PRESENCIAL","DIGITAL","HIBRIDO").contains(mode))bad("Modalidade inválida.");String city=text(p.municipalityCode(),7,false);if(!city.isEmpty())geo.municipality(city);String venue=text(p.venue(),500,false);if(!mode.equals("DIGITAL")&&(city.isEmpty()||venue.isEmpty()))bad("Eventos presenciais e híbridos precisam de município e local.");if(p.expectedRevision()<0||p.campaignId()!=null&&p.campaignId()<1)bad("Referência ou revisão inválida.");return new Definition(text(p.title(),180,true),text(p.description(),4000,true),start.toString(),end.toString(),mode,city,venue,p.registrationEnabled(),p.campaignId(),p.expectedRevision(),p.requestKey());}
 private void campaign(long org,Long id){if(id!=null&&db.queryForObject("SELECT count(*) FROM hub_campaigns WHERE id=? AND organization_id=? AND status<>'ARCHIVED'",Integer.class,id,org)==0)bad("Use uma campanha existente da própria organização.");}
 public Map<String,Object> create(String email,long org,Definition raw){var p=validate(raw);if(p.requestKey()==null||p.expectedRevision()!=0)bad("Informe requestKey e revisão zero para criar.");String hash=RadarBridge.hash(bridge.encode(p));return tx.execute(status->{orgLock(org);access.require(email,org,true);access.additionalWrite(org);var previous=db.queryForList("SELECT * FROM job_fairs WHERE organization_id=? AND create_key=?",org,p.requestKey());if(!previous.isEmpty()){if(!hash.equals(previous.getFirst().get("create_hash")))conflict();return decorate(previous.getFirst());}campaign(org,p.campaignId());long id=db.queryForObject("INSERT INTO job_fairs(organization_id,campaign_id,title,description,starts_at,ends_at,modality,municipality_code,state,venue,registration_enabled,create_key,create_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,org,p.campaignId(),p.title(),p.description(),java.sql.Timestamp.from(instant(p.startsAt())),java.sql.Timestamp.from(instant(p.endsAt())),p.modality(),p.municipalityCode().isEmpty()?null:p.municipalityCode(),p.municipalityCode().isEmpty()?null:geo.municipality(p.municipalityCode()).state(),p.venue(),p.registrationEnabled(),p.requestKey(),hash);audit(email,id,"CREATED");return decorate(event(org,id,false));});}
 public Map<String,Object> update(String email,long org,long id,Definition raw){var p=validate(raw);return write(email,org,id,p.expectedRevision(),"DETAILS_UPDATED",row->{if(!row.get("status").equals("DRAFT"))conflict();campaign(org,p.campaignId());if(db.queryForObject("SELECT count(*) FROM job_fair_sessions WHERE event_id=? AND (starts_at<? OR ends_at>?)",Integer.class,id,java.sql.Timestamp.from(instant(p.startsAt())),java.sql.Timestamp.from(instant(p.endsAt())))>0)bad("Ajuste a agenda antes de alterar o período.");db.update("UPDATE job_fairs SET campaign_id=?,title=?,description=?,starts_at=?,ends_at=?,modality=?,municipality_code=?,state=?,venue=?,registration_enabled=? WHERE id=?",p.campaignId(),p.title(),p.description(),java.sql.Timestamp.from(instant(p.startsAt())),java.sql.Timestamp.from(instant(p.endsAt())),p.modality(),p.municipalityCode().isEmpty()?null:p.municipalityCode(),p.municipalityCode().isEmpty()?null:geo.municipality(p.municipalityCode()).state(),p.venue(),p.registrationEnabled(),id);return null;});}
 public Map<String,Object> detail(String email,long org,long id){access.require(email,org,false);return decorate(event(org,id,false));}
 public Map<String,Object> list(String email,long org,long before,int limit,String state){access.require(email,org,false);page(before,limit);if(!Set.of("","DRAFT","PUBLISHED","CANCELLED","ARCHIVED").contains(state))bad("Situação inválida.");return pageRows(db.queryForList("SELECT * FROM job_fairs WHERE organization_id=? AND id<? AND (?='' OR status=?) ORDER BY id DESC LIMIT ?",org,before,state,state,limit+1),limit);}
 public Map<String,Object> publish(String email,long org,long id,Publication p){if(p==null||p.status()==null||!Set.of("DRAFT","PUBLISHED","CANCELLED","ARCHIVED").contains(p.status()))bad("Situação inválida.");return tx.execute(status->{orgLock(org);access.require(email,org,true);if(p.status().equals("PUBLISHED"))access.additionalWrite(org);var row=event(org,id,true);String old=row.get("status").toString();if(number(row,"revision")!=p.expectedRevision()||old.equals("ARCHIVED")||old.equals("CANCELLED")&&!p.status().equals("ARCHIVED"))conflict();if(old.equals(p.status()))return decorate(row);if(p.status().equals("PUBLISHED")){if(!time(row.get("ends_at")).isAfter(Instant.now()))bad("Não publique um evento encerrado.");if(db.queryForObject("SELECT count(*) FROM hub_profiles WHERE organization_id=? AND published=TRUE",Integer.class,org)==0)bad("Publique a apresentação institucional antes do evento.");if(row.get("campaign_id")!=null&&db.queryForObject("SELECT count(*) FROM hub_campaigns WHERE id=? AND organization_id=? AND status='PUBLISHED'",Integer.class,row.get("campaign_id"),org)==0)bad("A campanha vinculada também precisa estar publicada.");}db.update("UPDATE job_fairs SET status=?,published_at=CASE WHEN ?='PUBLISHED' THEN COALESCE(published_at,CURRENT_TIMESTAMP) ELSE published_at END WHERE id=?",p.status(),p.status(),id);bump(id);audit(email,id,"STATUS_"+p.status());return decorate(event(org,id,false));});}
 private String publicWhere(){return " FROM job_fairs e JOIN enterprise_organizations o ON o.id=e.organization_id JOIN hub_profiles h ON h.organization_id=o.id LEFT JOIN hub_campaigns p ON p.id=e.campaign_id WHERE o.status='ACTIVE' AND o.organization_type='ASSOCIATION' AND h.published=TRUE AND e.published_at IS NOT NULL AND e.status IN ('PUBLISHED','CANCELLED') AND (p.id IS NULL OR p.status='PUBLISHED')";}
 private String publicSelect(){return "SELECT e.id,e.organization_id,o.name AS organizer_name,e.title,e.description,e.starts_at,e.ends_at,e.modality,e.municipality_code,e.state,e.venue,e.registration_enabled,e.status";}
 public Map<String,Object> publicEvent(long id){var row=db.queryForList(publicSelect()+publicWhere()+" AND e.id=?",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Evento publicado não encontrado."));decorate(row);row.put("registrationOpen",Boolean.TRUE.equals(row.get("registration_enabled"))&&row.get("status").equals("PUBLISHED")&&time(row.get("ends_at")).isAfter(Instant.now()));return row;}
 public Map<String,Object> publicList(long before,int limit,String q,String region,String municipality,String state,String modality,String from,String to,boolean includePast){page(before,limit);q=text(q,120,false);if(!Set.of("","PRESENCIAL","DIGITAL","HIBRIDO").contains(modality)||!state.isEmpty()&&!geo.states().contains(state))bad("Filtro inválido.");var codes=geo.selection(region,municipality);var args=new ArrayList<Object>(List.of(before,q,"%"+q+"%","%"+q+"%"));String where=" AND e.id<? AND (?='' OR e.title ILIKE ? OR e.description ILIKE ?)";if(!includePast)where+=" AND e.ends_at>CURRENT_TIMESTAMP";if(!codes.isEmpty()){where+=" AND e.municipality_code IN ("+String.join(",",Collections.nCopies(codes.size(),"?"))+")";args.addAll(codes);}if(!state.isEmpty()){where+=" AND e.state=?";args.add(state);}if(!modality.isEmpty()){where+=" AND e.modality=?";args.add(modality);}if(!from.isEmpty()){where+=" AND e.ends_at>=?";args.add(java.sql.Timestamp.from(instant(from)));}if(!to.isEmpty()){where+=" AND e.starts_at<=?";args.add(java.sql.Timestamp.from(instant(to)));}if(!from.isEmpty()&&!to.isEmpty())period(instant(from),instant(to));args.add(limit+1);return pageRows(db.queryForList(publicSelect()+publicWhere()+where+" ORDER BY e.id DESC LIMIT ?",args.toArray()),limit);}
 private void openResources(long id){var row=publicEvent(id);if(!row.get("status").equals("PUBLISHED")||!time(row.get("ends_at")).isAfter(Instant.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"O evento está encerrado ou cancelado.");}
 private String accepted(){return "fc.status='ACCEPTED' AND c.verification_status='APPROVED' AND EXISTS(SELECT 1 FROM company_users cu WHERE cu.id=c.owner_user_id AND cu.email_verified=TRUE AND cu.account_status='ACTIVE') AND EXISTS(SELECT 1 FROM enterprise_organization_companies r WHERE r.organization_id=e.organization_id AND r.company_id=c.id AND r.relationship_type='ASSOCIATION_MEMBER' AND r.status='ACTIVE')";}
 public Map<String,Object> invite(String email,long org,long id,Reference p){if(p==null||p.id()<1)bad("Empresa inválida.");return write(email,org,id,p.expectedRevision(),"COMPANY_INVITED",row->{if(db.queryForObject("SELECT count(*) FROM enterprise_organization_companies r JOIN companies c ON c.id=r.company_id WHERE r.organization_id=? AND c.id=? AND r.relationship_type='ASSOCIATION_MEMBER' AND r.status='ACTIVE' AND c.verification_status='APPROVED'",Integer.class,org,p.id())==0)bad("Convide uma empresa real e ativa vinculada à associação.");db.update("INSERT INTO job_fair_companies(event_id,company_id) VALUES (?,?) ON CONFLICT(event_id,company_id) DO UPDATE SET status=CASE WHEN job_fair_companies.status='WITHDRAWN' THEN 'INVITED' ELSE job_fair_companies.status END,revision=job_fair_companies.revision+1,updated_at=CURRENT_TIMESTAMP",id,p.id());return null;});}
 private long companyOwner(String email){return db.queryForList("SELECT c.id FROM companies c JOIN company_users u ON u.id=c.owner_user_id WHERE LOWER(u.email)=LOWER(?) AND u.email_verified=TRUE AND u.account_status='ACTIVE' AND c.verification_status='APPROVED'",Long.class,email).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Somente o responsável verificado da empresa pode confirmar sua participação."));}
 public Map<String,Object> companyInvites(String email,long before,int limit){page(before,limit);long company=companyOwner(email);return pageRows(db.queryForList("SELECT e.id,e.organization_id,o.name AS organizer_name,e.title,e.description,e.starts_at,e.ends_at,e.modality,e.municipality_code,e.status,fc.status AS participation_status,fc.revision FROM job_fair_companies fc JOIN job_fairs e ON e.id=fc.event_id JOIN enterprise_organizations o ON o.id=e.organization_id WHERE fc.company_id=? AND e.id<? ORDER BY e.id DESC LIMIT ?",company,before,limit+1),limit);}
 public Map<String,Object> companyDecision(String email,long id,CompanyDecision p){if(p==null)bad("Informe a decisão.");long company=companyOwner(email);return tx.execute(status->{var roots=db.queryForList("SELECT organization_id FROM job_fairs WHERE id=?",id);if(roots.isEmpty())missing();long org=number(roots.getFirst(),"organization_id");orgLock(org);if(companyOwner(email)!=company)throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(p.accepted()&&db.queryForObject("SELECT count(*) FROM enterprise_organizations WHERE id=? AND status='ACTIVE' AND organization_type='ASSOCIATION'",Integer.class,org)==0)throw new ResponseStatusException(HttpStatus.FORBIDDEN);var e=event(org,id,true);var rows=db.queryForList("SELECT * FROM job_fair_companies WHERE event_id=? AND company_id=? FOR UPDATE",id,company);if(rows.isEmpty())missing();var row=rows.getFirst();if(number(row,"revision")!=p.expectedRevision())conflict();if(p.accepted()){if(row.get("status").equals("WITHDRAWN"))conflict();if(Set.of("CANCELLED","ARCHIVED").contains(e.get("status"))||!time(e.get("ends_at")).isAfter(Instant.now()))conflict();if(db.queryForObject("SELECT count(*) FROM enterprise_organization_companies WHERE organization_id=? AND company_id=? AND status='ACTIVE' AND relationship_type='ASSOCIATION_MEMBER'",Integer.class,org,company)==0)throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 db.update("UPDATE job_fair_companies SET status=?,revision=revision+1,accepted_at=CASE WHEN ? THEN CURRENT_TIMESTAMP ELSE NULL END,updated_at=CURRENT_TIMESTAMP WHERE event_id=? AND company_id=?",p.accepted()?"ACCEPTED":"WITHDRAWN",p.accepted(),id,company);bump(id);audit(email,id,p.accepted()?"COMPANY_ACCEPTED":"COMPANY_WITHDRAWN");return db.queryForMap("SELECT event_id,company_id,status,revision FROM job_fair_companies WHERE event_id=? AND company_id=?",id,company);});}
 public Map<String,Object> companies(String email,long org,long id,long before,int limit){detail(email,org,id);page(before,limit);return HubService.pageResult(db.queryForList("SELECT c.id,c.trade_name,fc.status,fc.revision FROM job_fair_companies fc JOIN companies c ON c.id=fc.company_id WHERE fc.event_id=? AND c.id<? ORDER BY c.id DESC LIMIT ?",id,before,limit+1),limit);}
 public Map<String,Object> publicCompanies(long id,long before,int limit){openResources(id);page(before,limit);return HubService.pageResult(db.queryForList("SELECT c.id,c.trade_name,c.public_slug FROM job_fair_companies fc JOIN job_fairs e ON e.id=fc.event_id JOIN companies c ON c.id=fc.company_id WHERE e.id=? AND c.id<? AND "+accepted()+" ORDER BY c.id DESC LIMIT ?",id,before,limit+1),limit);}
 public Map<String,Object> removeCompany(String email,long org,long id,long company,long revision){return write(email,org,id,revision,"COMPANY_REMOVED",row->{if(db.update("UPDATE job_fair_companies SET status='WITHDRAWN',revision=revision+1,accepted_at=NULL,updated_at=CURRENT_TIMESTAMP WHERE event_id=? AND company_id=?",id,company)==0)missing();return null;});}
 public Map<String,Object> linkJob(String email,long org,long id,Reference p){if(p==null||p.id()<1)bad("Vaga inválida.");return write(email,org,id,p.expectedRevision(),"JOB_LINKED",row->{var jobs=db.queryForList("SELECT l.company_id FROM company_listings l JOIN companies c ON c.id=l.company_id JOIN job_fair_companies fc ON fc.company_id=c.id JOIN job_fairs e ON e.id=fc.event_id WHERE e.id=? AND l.id=? AND "+accepted()+" AND "+CompanyRadarController.PUBLIC_JOB_CONDITION,id,p.id());if(jobs.isEmpty())bad("Vincule uma vaga pública e disponível de empresa participante confirmada. Estágios devem atender às regras de pagamento existentes.");db.update("INSERT INTO job_fair_listings(event_id,company_id,listing_id) VALUES (?,?,?) ON CONFLICT DO NOTHING",id,jobs.getFirst().get("company_id"),p.id());return null;});}
 public Map<String,Object> publicJobs(long id,long before,int limit,String area,String modality){openResources(id);page(before,limit);text(area,120,false);text(modality,40,false);return HubService.pageResult(db.queryForList("SELECT l.id,l.title,l.area,l.location,l.modality,l.requirements,l.workload,l.benefits,l.salary,l.headcount,c.trade_name AS company_name,c.public_slug FROM job_fair_listings j JOIN job_fair_companies fc ON fc.event_id=j.event_id AND fc.company_id=j.company_id JOIN job_fairs e ON e.id=j.event_id JOIN company_listings l ON l.id=j.listing_id JOIN companies c ON c.id=l.company_id WHERE e.id=? AND l.id<? AND "+accepted()+" AND "+CompanyRadarController.PUBLIC_JOB_CONDITION+" AND (?='' OR l.area ILIKE ?) AND (?='' OR l.modality=?) ORDER BY l.id DESC LIMIT ?",id,before,area,"%"+area+"%",modality,modality,limit+1),limit);}
 public Map<String,Object> linkCourse(String email,long org,long id,Reference p){if(p==null||p.id()<1)bad("Curso inválido.");access.require(email,org,true);bridge.get("/public/capacita/hub/courses/"+p.id());return write(email,org,id,p.expectedRevision(),"COURSE_LINKED",row->{db.update("INSERT INTO job_fair_courses(event_id,course_id) VALUES (?,?) ON CONFLICT DO NOTHING",id,p.id());return null;});}
 public Map<String,Object> publicCourses(long id,long before,int limit){openResources(id);page(before,limit);if(limit>20)bad("Consulte até vinte cursos por página.");var refs=db.queryForList("SELECT course_id AS id FROM job_fair_courses WHERE event_id=? AND course_id<? ORDER BY course_id DESC LIMIT ?",id,before,limit+1);var result=new LinkedHashMap<>(HubService.pageResult(refs,limit));var items=new ArrayList<Object>();boolean unavailable=false;long started=System.nanoTime();for(var ref:refs.stream().limit(limit).toList()){if(System.nanoTime()-started>2_000_000_000L){unavailable=true;break;}try{items.add(bridge.convert(bridge.get("/public/capacita/hub/courses/"+ref.get("id")),Map.class));}catch(ResponseStatusException failure){if(failure.getStatusCode().value()!=404){unavailable=true;break;}}}result.put("items",items);result.put("sourceStatus",unavailable?"UNAVAILABLE":"AVAILABLE");return result;}
 public Map<String,Object> session(String email,long org,long id,long sessionId,Session p){if(p==null||p.kind()==null||!Set.of("TALK","WORKSHOP").contains(p.kind()))bad("Tipo de atividade inválido.");var from=instant(p.startsAt());var to=instant(p.endsAt());period(from,to);String title=text(p.title(),180,true),description=text(p.description(),2000,true),speaker=text(p.speakerName(),180,false);if(!speaker.isBlank()&&!p.speakerConsent())bad("Confirme autorização para divulgar o nome do palestrante.");return write(email,org,id,p.expectedRevision(),"AGENDA_UPDATED",row->{if(from.isBefore(time(row.get("starts_at")))||to.isAfter(time(row.get("ends_at"))))bad("A atividade precisa estar dentro do período do evento.");if(sessionId==0)db.update("INSERT INTO job_fair_sessions(event_id,kind,title,description,speaker_name,public_speaker_consent,starts_at,ends_at) VALUES (?,?,?,?,?,?,?,?)",id,p.kind(),title,description,speaker,p.speakerConsent(),java.sql.Timestamp.from(from),java.sql.Timestamp.from(to));else if(db.update("UPDATE job_fair_sessions SET kind=?,title=?,description=?,speaker_name=?,public_speaker_consent=?,starts_at=?,ends_at=? WHERE event_id=? AND id=?",p.kind(),title,description,speaker,p.speakerConsent(),java.sql.Timestamp.from(from),java.sql.Timestamp.from(to),id,sessionId)==0)missing();return null;});}
 public Map<String,Object> sessions(String email,long org,long id,long before,int limit,boolean publicView){if(publicView)openResources(id);else detail(email,org,id);page(before,limit);return HubService.pageResult(db.queryForList("SELECT id,kind,title,description,speaker_name,starts_at,ends_at FROM job_fair_sessions WHERE event_id=? AND id<? ORDER BY id DESC LIMIT ?",id,before,limit+1),limit);}
 public Map<String,Object> remove(String email,long org,long id,String kind,long resource,long revision){String table=switch(kind){case "jobs"->"job_fair_listings";case "courses"->"job_fair_courses";case "sessions"->"job_fair_sessions";default->throw new ResponseStatusException(HttpStatus.BAD_REQUEST);};String column=switch(kind){case "jobs"->"listing_id";case "courses"->"course_id";default->"id";};return write(email,org,id,revision,"RESOURCE_UNLINKED",row->{if(db.update("DELETE FROM "+table+" WHERE event_id=? AND "+column+"=?",id,resource)==0)missing();return null;});}
 public Map<String,Object> indicators(String email,long org,long id){access.require(email,org,false);var e=event(org,id,false);var result=new LinkedHashMap<String,Object>();result.put("event",decorate(e));result.put("confirmedCompanyRecords",db.queryForObject("SELECT count(*) FROM job_fair_companies WHERE event_id=? AND status='ACCEPTED'",Long.class,id));result.put("linkedJobRecords",db.queryForObject("SELECT count(*) FROM job_fair_listings WHERE event_id=?",Long.class,id));result.put("linkedCourseReferences",db.queryForObject("SELECT count(*) FROM job_fair_courses WHERE event_id=?",Long.class,id));result.put("agendaItems",db.queryForObject("SELECT count(*) FROM job_fair_sessions WHERE event_id=?",Long.class,id));boolean available=true;long total=0;for(String source:List.of("opportunities","learning")){try{var counts=bridge.post("/integrations/job-fairs/"+source+"/counts",new CountQuery(org,List.of(id)));long count=counts.path("counts").path(Long.toString(id)).asLong(-1);if(count<0)throw new IllegalStateException();result.put(source,Map.of("status","AVAILABLE","registeredAccounts",count));total+=count;}catch(RuntimeException error){available=false;result.put(source,Map.of("status","UNAVAILABLE"));}}result.put("registeredAccountsTotal",available?total:null);result.put("notice","Contas com inscrição ativa, não pessoas únicas, presença física ou contratação. A mesma pessoa pode ter contas independentes. Indisponibilidade de uma fonte não é contada como zero.");return result;}
}
